export const modules = records.map(([title,desc,hours,count,deps],index) => ({
  id:'m'+String(index).padStart(2,'0'),index,title,desc,hours,count,deps,
  stage:stages[index<6?0:index<11?1:2]
}));
export const moduleById = Object.assign(Object.create(null),Object.fromEntries(modules.map(m=>[m.id,m])));
const cache = new Map();
export async function content(id) {
  if (!moduleById[id] && id!=='catalogue') throw Error('Неизвестный модуль.');
  if (!cache.has(id)) {
    const path=new URL('../content/'+id+'.json',import.meta.url);
    cache.set(id,fetch(path).then(r=>{
      if (!r.ok) throw Error('Не удалось загрузить учебный материал.');
      return r.json();
    }).catch(e=>{cache.delete(id);throw e;}));
  }
  return cache.get(id);
}
export const plural=(n,forms)=>forms[(n%100>=11&&n%100<=14)?2:n%10===1?0:n%10>=2&&n%10<=4?1:2];
export const moduleCount=n=>n+' '+plural(n,['модуль','модуля','модулей']);
export const taskCount=n=>n+' '+plural(n,['задача','задачи','задач']);
